import{_ as n,C as o,o as i,c,j as t,a as d,E as a,ag as l}from"./chunks/framework.HG0H2VLS.js";const k=JSON.parse('{"title":"Button","description":"","frontmatter":{},"headers":[],"relativePath":"components/button.md","filePath":"components/button.md"}'),h={name:"components/button.md"},b={id:"button",tabindex:"-1"};function g(p,e,u,m,x,y){const r=o("Badge"),s=o("ComponentDemo");return i(),c("div",null,[e[3]||(e[3]=t("hr",null,null,-1)),e[4]||(e[4]=t("h2",{id:"title-button",tabindex:"-1"},[d("title: Button "),t("a",{class:"header-anchor",href:"#title-button","aria-label":'Permalink to "title: Button"'},"​")],-1)),t("h1",b,[e[0]||(e[0]=d("Button ",-1)),a(r,{type:"info",text:"Design System"}),e[1]||(e[1]=d()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#button","aria-label":'Permalink to "Button <Badge type="info" text="Design System" />"'},"​",-1))]),e[5]||(e[5]=t("blockquote",null,[t("p",null,"primary, secondary, tertiary, alert, alert-outline, icon-only variants")],-1)),a(s,{src:"/demos/src/components/Button/Button.html"}),e[6]||(e[6]=l('<h2 id="btn-2xs-—-a-24x24-icon-size-that-led-figma-and-is-now-redundant" tabindex="-1"><code>btn--2xs</code> — a 24x24 icon size that led Figma, and is now REDUNDANT <a class="header-anchor" href="#btn-2xs-—-a-24x24-icon-size-that-led-figma-and-is-now-redundant" aria-label="Permalink to &quot;`btn--2xs` — a 24x24 icon size that led Figma, and is now REDUNDANT&quot;">​</a></h2><p>Added 2026-08-25 while building <strong>RoomCard</strong> (<code>3470:84951</code>), which places Button instances at <strong>24x24</strong> with a 12px icon. At the time no existing size produced that.</p><p><strong>Superseded 2026-08-28: the designer squared off the xs icon size, so <code>.btn--icon.btn--xs</code> IS 24x24 now and this class duplicates it exactly</strong> — same width, min-height, padding, radius and icon size. Re-read from the set rather than assumed: every <code>Icon Only=True, Size=xs</code> variant measures 24x24 across all three Types and all five States (Secondary <code>2926:3565</code> + Hover <code>2926:3577</code> / Focus <code>2926:3613</code> / Pressed <code>2926:3593</code> / Disabled <code>2926:3595</code>; Primary <code>2926:3559</code>…; Tertiary <code>2926:3571</code>…), and <code>2926:3565</code> binds <code>--ao-spacing-6</code>, <code>--ao-icon-size-xs</code>, <code>--ao-radius-sm</code> (rebound to <code>--ao-radius-md</code> 2026-09-28).</p><table tabindex="0"><thead><tr><th>Size</th><th>Icon-only, as drawn in the Button set (<code>53:2489</code>)</th></tr></thead><tbody><tr><td>base</td><td>40x40</td></tr><tr><td>sm</td><td>32x32</td></tr><tr><td>xs</td><td><strong>24x24 — since 2026-08-28. Was 32x24 (Secondary/Tertiary), 28x24 (Primary)</strong></td></tr><tr><td>2xs</td><td>24x24 — <strong>exists only in code, and now duplicates xs</strong></td></tr></tbody></table><p><strong>Not retired in the same change, deliberately.</strong> <code>btn--2xs</code> has 161 usages across TableCard, RoomCard, AttendeeCard and SeatingHeader, and its literal string is baked into Code Connect snippets already published to Figma — so collapsing it into <code>xs</code> is a migration plus a <code>code-connect:publish</code>, not a tidy-up to fold into a one-line size fix. Flagged for the designer to schedule.</p><p>Cautionary note for the next audit: this section previously stated xs was 32x24 as settled fact, and that statement outlived the Figma it described. A dimension recorded in prose here is a snapshot, not a spec — re-read the set before relying on one.</p><p>So RoomCard&#39;s buttons are <strong>resized instances</strong>, a Figma-side override rather than a variant. The designer chose to formalise the size in code (2026-08-25):</p><div class="language-css vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">.btn--icon.btn--2xs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { 24</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">x</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">24, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">padding</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 0, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">--ao-radius-sm</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, 12</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">px</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> icon</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>Two things to know about it:</p><ul><li><strong>It is icon-only on purpose.</strong> There is no text <code>.btn--2xs</code>, because Figma defines none, and inventing one would be a variant with no Figma counterpart. Writing <code>btn btn--2xs</code> without <code>btn--icon</code> therefore does nothing — the rule is a two-class combination, matching the house style of <code>.btn--icon.btn--sm</code> / <code>.btn--icon.btn--xs</code>.</li><li><strong>Its radius is set explicitly</strong>, unlike <code>--xs</code> which inherits <code>--ao-radius-md</code> (since 2026-09-28) from the base <code>.btn--xs</code> rule. There is no base <code>.btn--2xs</code>, so nothing would carry it.</li><li>The icon rule targets <strong>both</strong> <code>[data-lucide]</code> and <code>svg</code>. <code>lucide.createIcons()</code> replaces the <code>&lt;i&gt;</code> with an <code>&lt;svg&gt;</code>, so an <code>[data-lucide]</code>-only selector is fragile. Verified 12x12 rendered.</li></ul><blockquote><p><strong>Figma follow-up:</strong> add a <code>Size=2xs</code> icon-only variant to the Button set so Figma and code agree, or resize RoomCard&#39;s instances to <code>xs</code>. Until then this row is code-ahead-of-Figma. <strong>Second consumer waiting:</strong> AttendeeCard&#39;s <code>.attendee-card__action</code> is the same geometry (24px box, 12px icon, <code>--ao-radius-sm</code>) built as scoped CSS — worth folding onto <code>btn--2xs</code>.</p></blockquote><h2 id="resting-shadow-—-shadow-2xs-2026-09-23-—-removed" tabindex="-1">Resting shadow — <code>shadow/2xs</code> (2026-09-23) — REMOVED <a class="header-anchor" href="#resting-shadow-—-shadow-2xs-2026-09-23-—-removed" aria-label="Permalink to &quot;Resting shadow — `shadow/2xs` (2026-09-23) — REMOVED&quot;">​</a></h2><blockquote><p><strong>REMOVED for now — designer, 2026-09-23.</strong> The designer took every shadow added on 2026-09-23 back off; this section is kept as the record of what was there. The CSS declaration is gone, so a return is one line.</p></blockquote><p>The designer added Figma&#39;s <code>shadow/2xs</code> (0 1px 0, black 5%; 10% in dark) to the filter bar elements in the Listings frame (<code>3645:148870</code>) and chose to make it <strong>component-wide</strong> rather than scoped to the filter bar, so every instance gets it: every <code>.btn--secondary</code>, icon-only included. In Figma it currently sits on the filter bar&#39;s instances (the sidebar&#39;s search Input has none), so Figma&#39;s component defaults trail this.</p><p>Token: <code>--ao-shadow-2xs</code>. Only Secondary: Primary, Tertiary and the alert types are unchanged. The focus-visible ring replaces it while focused. A disabled Secondary keeps the shadow (the disabled rule does not reset box-shadow); Figma&#39;s disabled state has not been checked.</p><p><strong>2026-10-16 (TASK-555946):</strong> Alert hover/focus/pressed now go DARKER than the default (RedRadix/12 / 13), mirroring the primary button; Figma&#39;s 18 hover/focus/pressed Alert variants rebound to match, and the solid Alert Default fill was rebound from the <code>Red/500</code> primitive to <code>surface/error</code> (code already used it). Outline Default in Figma still uses <code>Red/500</code> for stroke/text while code uses <code>border-error</code> / <code>text-error</code> — flagged, not changed.</p><p><strong>2026-10-27 (Mark): alert + primary hover one step lighter, light modes only.</strong> Lagoon and RedRadix both had an 11 → 12 cliff (≈0.22 OKLCH-L; other steps ≤ 0.12), so hover read as near-black. Each ramp gained a step: new <strong>Lagoon/12 <code>#036170</code></strong> and <strong>RedRadix/12 <code>#A5242F</code></strong>, the old 12/13/14 renamed 13/14/15 (same values and IDs). Primary hover/pressed in Light + CCLight → Lagoon/12 / 13. Alert got its own Semantic tokens <code>components/global/button/alert-bg-hover</code> / <code>-pressed</code> (<code>--ao-btn-alert-bg-hover</code> / <code>-pressed</code>): Light, CCLight and ChatLight → RedRadix/12 / 13; Dark, CCDark and ChatDark keep <code>#641723</code> / <code>#3B1219</code>. Figma&#39;s 24 Alert variants rebound (6 hover fills, 6 focus fills, 6 focus rings, 6 pressed fills). Outline Default&#39;s <code>Red/500</code> stroke/text is still the open item from 2026-10-16.</p><p><strong>2026-10-27 (Mark): dark primary = light lagoon, dark text.</strong> Dark + CCDark: <code>primary-bg</code> Lagoon/8 <code>#30B6C2</code>, <code>-hover</code> (and <code>-focus</code>, which aliases it) Lagoon/7 <code>#77CAD0</code>, <code>-pressed</code> Lagoon/9 <code>#009FBA</code>, <code>primary-text</code> / <code>-text-hover</code> Lagoon/15 <code>#00191F</code>. Light, CCLight and the Chat modes unchanged. Alert + Alert Outline text and icons now use <code>--ao-text-invert</code> (Figma: <code>text/invert</code>) instead of <code>primary-text</code>, so they stay white. <code>.btn .spinner--inverted</code> inherits the button&#39;s text colour. Figma drift fixed: Primary Hover base (<code>53:2490</code>) had its fill on the raw <code>Lagoon/11</code> primitive; now <code>primary-bg-hover</code>.</p><p><strong>2026-10-27 (Mark): dark alert mirrors dark primary.</strong> New Semantic <code>components/global/button/alert-bg</code> (<code>--ao-btn-alert-bg</code>, VariableID:4446:4845) and <code>alert-text</code> (<code>--ao-btn-alert-text</code>, 4446:4846). Light, CCLight, ChatLight and ChatDark keep today&#39;s values (RedRadix/11 bg, white text); Dark + CCDark (revised same day): bg RedRadix/9 <code>#E5484D</code>, text RedRadix/15 <code>#201314</code>, hover/focus RedRadix/8 <code>#F07374</code>, pressed RedRadix/7 <code>#F8999A</code> — lighter as you interact. RedRadix 8 and 7 were re-spaced evenly between 9 and 6 (old 8 <code>#EB8E90</code> read pink); see docs/tokens-reference.md. Figma: Alert Default fills → <code>alert-bg</code>; every Alert text/icon on a red fill (147 paints, incl. Alert Outline hover/focus/pressed) → <code>alert-text</code>, plus 8 paints in Dropdowns&#39; nested alert button. Alert Outline Default is unchanged (its dark border <code>#CE2C31</code> is 2.8:1 on the page — pre-existing, text is 6.1:1).</p><h2 id="variants" tabindex="-1">Variants <a class="header-anchor" href="#variants" aria-label="Permalink to &quot;Variants&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Sizes</th><th>States</th></tr></thead><tbody><tr><td>Default (Primary)</td><td>base, sm, xs</td><td>Default, Hover, Focus, Pressed, Disabled</td></tr><tr><td>Secondary</td><td>base, sm, xs</td><td>Default, Hover, Focus, Pressed, Disabled</td></tr><tr><td>Tertiary</td><td>base, sm, xs</td><td>Default, Hover, Focus, Pressed, Disabled</td></tr><tr><td>Alert</td><td>base, sm, xs</td><td>Default, Hover, Focus, Pressed</td></tr><tr><td>Alert Outline</td><td>base, sm, xs</td><td>Default, Hover, Focus, Pressed</td></tr><tr><td>Icon Only</td><td>base, sm, xs</td><td>Default, Hover, Focus, Pressed, Disabled</td></tr><tr><td>Icon Only</td><td><strong>2xs</strong> (code-only)</td><td>Default, Hover, Focus, Pressed, Disabled</td></tr></tbody></table><h2 id="css-classes" tabindex="-1">CSS Classes <a class="header-anchor" href="#css-classes" aria-label="Permalink to &quot;CSS Classes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Figma Property</th><th>Values</th><th>CSS Class</th></tr></thead><tbody><tr><td><code>Type</code></td><td>Default</td><td><code>.btn--primary</code></td></tr><tr><td><code>Type</code></td><td>Secondary</td><td><code>.btn--secondary</code></td></tr><tr><td><code>Type</code></td><td>Tertiary</td><td><code>.btn--tertiary</code></td></tr><tr><td><code>Type</code></td><td>Alert</td><td><code>.btn--alert</code></td></tr><tr><td><code>Type</code></td><td>Alert Outline</td><td><code>.btn--alert-outline</code></td></tr><tr><td><code>Type</code></td><td>Secondary / Action, Primary / Action</td><td><em>(no single class — a split is <code>.btn-group</code> / <code>.btn-group--brand</code> with two buttons; see ButtonGroup notes)</em></td></tr><tr><td><code>Size</code></td><td>base</td><td><em>(none — default)</em></td></tr><tr><td><code>Size</code></td><td>sm</td><td><code>.btn--sm</code></td></tr><tr><td><code>Size</code></td><td>xs</td><td><code>.btn--xs</code></td></tr></tbody></table><blockquote><p><strong>2026-09-28:</strong> Size=xs text is now <strong>SemiBold</strong> (<code>--ao-font-semibold</code>) — rebound in Figma on all 38 xs variants (<code>font/weight/SemiBold</code>, was Medium) at the designer&#39;s request. Radius is now <code>--ao-radius-md</code> (was <code>radius-sm</code>) — all 38 xs variants rebound to <code>border/radius/radius-md</code> the same day.</p></blockquote><p>| <code>Size</code> | <em>(none — see below)</em> | <code>.btn--icon.btn--2xs</code> | | <code>Icon Only</code> | True | <code>.btn--icon</code> | | <code>State</code> | Disabled | <code>disabled</code> attr / <code>.btn--disabled</code> |</p><h2 id="token-mapping" tabindex="-1">Token Mapping <a class="header-anchor" href="#token-mapping" aria-label="Permalink to &quot;Token Mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Figma Variable</th><th>CSS Variable</th><th>Role</th></tr></thead><tbody><tr><td><code>--ao-btn-primary-bg</code></td><td><code>--ao-btn-primary-bg</code></td><td>Primary bg</td></tr><tr><td><code>--ao-btn-primary-bg-hover</code></td><td><code>--ao-btn-primary-bg-hover</code></td><td>Primary hover + focus bg</td></tr><tr><td><code>--ao-btn-primary-bg-pressed</code></td><td><code>--ao-btn-primary-bg-pressed</code></td><td>Primary active bg</td></tr><tr><td><code>--ao-btn-primary-text</code></td><td><code>--ao-btn-primary-text</code></td><td>Primary text (theme-invariant)</td></tr><tr><td><code>--ao-btn-primary-text-hover</code></td><td><code>--ao-btn-primary-text-hover</code></td><td>Primary hover text</td></tr><tr><td><code>--ao-btn-secondary-bg</code></td><td><code>--ao-btn-secondary-bg</code></td><td>Secondary bg (transparent)</td></tr><tr><td><code>--ao-btn-secondary-bg-hover</code></td><td><code>--ao-btn-secondary-bg-hover</code></td><td>Secondary hover + focus bg</td></tr><tr><td><code>--ao-btn-secondary-bg-pressed</code></td><td><code>--ao-btn-secondary-bg-pressed</code></td><td>Secondary active bg</td></tr><tr><td><code>--ao-btn-secondary-border</code></td><td><code>--ao-btn-secondary-border</code></td><td>Secondary border (default + pressed + focus ring)</td></tr><tr><td><code>--ao-btn-secondary-border-hover</code></td><td><code>--ao-btn-secondary-border-hover</code></td><td>Secondary hover border</td></tr><tr><td><code>--ao-btn-secondary-text</code></td><td><code>--ao-btn-secondary-text</code></td><td>Secondary text</td></tr><tr><td><code>--ao-btn-secondary-text-hover</code></td><td><code>--ao-btn-secondary-text-hover</code></td><td>Secondary hover text</td></tr><tr><td><code>--ao-btn-tertiary-bg</code></td><td><code>--ao-btn-tertiary-bg</code></td><td>Tertiary bg (transparent); also focus bg</td></tr><tr><td><code>--ao-btn-tertiary-bg-hover</code></td><td><code>--ao-btn-tertiary-bg-hover</code></td><td>Tertiary hover bg</td></tr><tr><td><code>--ao-btn-tertiary-bg-pressed</code></td><td><code>--ao-btn-tertiary-bg-pressed</code></td><td>Tertiary active bg</td></tr><tr><td><code>--ao-btn-tertiary-text</code></td><td><code>--ao-btn-tertiary-text</code></td><td>Tertiary text</td></tr><tr><td><code>--ao-btn-tertiary-text-hover</code></td><td><code>--ao-btn-tertiary-text-hover</code></td><td>Tertiary hover text</td></tr><tr><td><code>--ao-btn-bg-disabled</code></td><td><code>--ao-btn-bg-disabled</code></td><td>Disabled bg (all variants)</td></tr><tr><td><code>--ao-btn-text-disabled</code></td><td><code>--ao-btn-text-disabled</code></td><td>Disabled text (all variants)</td></tr><tr><td><code>--ao-border-secondary</code></td><td><code>--ao-border-secondary</code></td><td>Tertiary focus ring</td></tr><tr><td><code>--ao-text-error</code></td><td><code>--ao-text-error</code></td><td>Alert Outline text</td></tr><tr><td><code>--ao-border-error</code></td><td><code>--ao-border-error</code></td><td>Alert Outline border</td></tr><tr><td><code>--ao-surface-error</code></td><td><code>--ao-surface-error</code></td><td>Alert bg (maps from Figma <code>Red/500</code>)</td></tr><tr><td><code>--ao-surface-primary</code></td><td><code>--ao-surface-primary</code></td><td>Alert Outline bg; inner border on primary/secondary focus</td></tr><tr><td><code>--ao-radius-md</code></td><td><code>--ao-radius-md</code></td><td>Default corner radius (8px)</td></tr><tr><td><code>--ao-radius-sm</code></td><td><code>--ao-radius-sm</code></td><td>Small button corner radius (4px)</td></tr><tr><td><code>--ao-spacing-8</code></td><td><code>--ao-spacing-8</code></td><td>Base height (40px)</td></tr><tr><td><code>--ao-spacing-7</code></td><td><code>--ao-spacing-7</code></td><td>Small height (32px)</td></tr><tr><td><code>--ao-font-fluid-xs</code></td><td><code>--ao-font-fluid-xs</code></td><td>Base font size (14px)</td></tr><tr><td><code>--ao-font-fluid-xxs</code></td><td><code>--ao-font-fluid-xxs</code></td><td>Small font size (12px)</td></tr><tr><td><code>--ao-leading-xs</code></td><td><code>--ao-leading-xs</code></td><td>Line height (16px)</td></tr><tr><td><code>--ao-icon-size-sm</code></td><td><code>--ao-icon-size-sm</code></td><td>Icon size inside base/sm buttons (16px)</td></tr><tr><td><code>--ao-icon-size-xs</code></td><td><code>--ao-icon-size-xs</code></td><td>Icon size inside xs buttons (12px)</td></tr><tr><td><code>--ao-spacing-2</code> / <code>--ao-spacing-3</code></td><td>same</td><td>xs vertical / horizontal padding (6px / 8px)</td></tr><tr><td><code>--ao-spacing-6</code></td><td><code>--ao-spacing-6</code></td><td>xs icon-only height (24px)</td></tr></tbody></table><h2 id="token-gaps" tabindex="-1">Token Gaps <a class="header-anchor" href="#token-gaps" aria-label="Permalink to &quot;Token Gaps&quot;">​</a></h2><table tabindex="0"><thead><tr><th>State</th><th>Figma Primitive</th><th>Value</th><th>Token Needed</th><th>Affected Variants</th><th>Status</th></tr></thead><tbody><tr><td>Primary focus ring</td><td><code>--ao-surface-brand-light</code></td><td><code>#3a8fff</code></td><td>✓ resolved</td><td>Primary</td><td>✅ Implemented</td></tr><tr><td>Alert hover bg</td><td><code>components/global/button/alert-bg-hover</code></td><td>light <code>#A5242F</code> (RedRadix/12) · dark <code>#641723</code> (RedRadix/13)</td><td><code>--ao-btn-alert-bg-hover</code></td><td>Alert, Alert Outline</td><td>✅ Semantic token (2026-10-27)</td></tr><tr><td>Alert focus ring</td><td><code>components/global/button/alert-bg-hover</code></td><td>as hover</td><td><code>--ao-btn-alert-bg-hover</code></td><td>Alert, Alert Outline</td><td>✅ Semantic token (2026-10-27); Figma ring was still on <code>Red/400</code>, rebound</td></tr><tr><td>Alert pressed</td><td><code>components/global/button/alert-bg-pressed</code></td><td>light <code>#641723</code> (RedRadix/13) · dark <code>#3B1219</code> (RedRadix/14)</td><td><code>--ao-btn-alert-bg-pressed</code></td><td>Alert, Alert Outline</td><td>✅ Semantic token (2026-10-27)</td></tr></tbody></table><p><strong>Note:</strong> since 2026-10-27 Alert hover/focus/pressed use the Semantic tokens above; <code>Button.css</code> has no hardcoded alert hexes left.</p><h2 id="icon-slots" tabindex="-1">Icon Slots <a class="header-anchor" href="#icon-slots" aria-label="Permalink to &quot;Icon Slots&quot;">​</a></h2><p>Figma default for all text-button variants has <code>showLeftIcon=true</code> — both slots are visible.</p><table tabindex="0"><thead><tr><th>Slot</th><th>Placement</th><th>Default Lucide icon</th><th>HTML</th></tr></thead><tbody><tr><td>Left / leading</td><td>Before label text</td><td><code>chevron-right</code></td><td><code>&lt;i data-lucide=&quot;chevron-right&quot; aria-hidden=&quot;true&quot;&gt;&lt;/i&gt;</code></td></tr><tr><td>Right / trailing</td><td>After label text</td><td><code>arrow-right</code></td><td><code>&lt;i data-lucide=&quot;arrow-right&quot; aria-hidden=&quot;true&quot;&gt;&lt;/i&gt;</code></td></tr></tbody></table><ul><li><strong>Figma default (both icons):</strong> <code>&lt;i chevron-right&gt;</code> Label <code>&lt;i arrow-right&gt;</code> — use this in parent components unless Figma shows otherwise</li><li><strong>Icon-only buttons (<code>btn--icon</code>):</strong> single centred icon only, no left or right slot</li></ul><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li><code>button/base</code> typography: <code>--ao-font-fluid-xs</code> (14px), <code>--ao-font-semibold</code> (600), <code>--ao-leading-xs</code> (16px)</li><li><code>button/sm</code> typography: <code>--ao-font-fluid-xxs</code> (12px), <code>--ao-font-semibold</code> (600), <code>--ao-leading-xs</code> (16px)</li><li><code>button/xs</code> typography: <code>--ao-font-fluid-xxs</code> (12px), <code>--ao-font-semibold</code> (600, since 2026-09-28), <code>--ao-leading-xs</code> (16px). xs differs from sm: <code>--ao-spacing-1</code> gap (4px), 12px icons (<code>--ao-icon-size-xs</code>), and explicit vertical padding (<code>--ao-spacing-2</code>) rather than a fixed-height token — 28px text / 24px icon-only have no spacing token, so xs uses Figma&#39;s <code>py-2</code> padding directly.</li><li>Secondary = <strong>transparent</strong> bg + <code>--ao-btn-secondary-border</code> (visually outlined)</li><li>Tertiary = <strong>transparent</strong> bg + <strong>no border</strong> (ghost/text button); uses dedicated <code>--ao-btn-tertiary-*</code> tokens</li><li>Tertiary hover bg: <code>--ao-btn-tertiary-bg-hover</code> (#F3F4F6); focus ring: <code>0 0 0 2px --ao-border-secondary</code> (no inner white border)</li><li>Secondary and tertiary now have dedicated token sets — no longer sharing <code>--ao-btn-secondary-*</code></li><li>Disabled: <code>--ao-btn-bg-disabled</code> for bg/border, <code>--ao-btn-text-disabled</code> for text (separate tokens)</li><li>Alert background uses Figma primitive <code>Red/500</code> → maps to <code>--ao-surface-error</code> (#ef4444)</li><li><code>.btn--lg</code> does <strong>not</strong> exist in Figma — removed from implementation</li><li>Figma exports the component collection key as <code>compnonents</code> (typo — do not fix in tokens)</li></ul><h2 id="figma" tabindex="-1">Figma <a class="header-anchor" href="#figma" aria-label="Permalink to &quot;Figma&quot;">​</a></h2><p><a href="https://www.figma.com/design/Lus07xi8pPXLN87sQIyrEt/Affino-AI---Design-System?node-id=53-2489" target="_blank" rel="noreferrer">Open in Figma</a></p>',38))])}const v=n(h,[["render",g]]);export{k as __pageData,v as default};
